import sqlite3

from agents import function_tool

DB_PATH = "repos.db"


@function_tool
def update_repo_description_record(repo_name: str, description: str, homepage: str = "") -> str:
    with sqlite3.connect(DB_PATH) as conn:
        cur = conn.cursor()
        cur.execute("SELECT id FROM repositories WHERE name = ?", (repo_name,))
        row = cur.fetchone()
        if row is None:
            return f"Repository '{repo_name}' not found"
        if homepage:
            cur.execute(
                "UPDATE repositories SET description = ?, homepage = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
                (description, homepage, row[0]),
            )
        else:
            cur.execute(
                "UPDATE repositories SET description = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?",
                (description, row[0]),
            )
    return f"Updated repository '{repo_name}'"

import shutil
from pathlib import Path

from langchain_core.tools import tool


def _resolve_inside(root: Path, rel: str) -> Path:
    target = (root / rel).resolve()
    if root not in target.parents and target != root:
        raise ValueError(f"Path escapes repository: {rel}")
    return target


@tool
def move_file_in_repo(repo_path: str, source: str, destination: str) -> str:
    root = Path(repo_path).resolve()
    try:
        src = _resolve_inside(root, source)
        dst = _resolve_inside(root, destination)
    except ValueError as exc:
        return str(exc)
    if not src.is_file():
        return f"Source file not found: {source}"
    if dst.exists():
        return f"Destination already exists: {destination}"
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.move(str(src), str(dst))
    return f"Moved {source} to {destination}"

import os
from dataclasses import dataclass, field

import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("repo-admin")

API = "https://api.github.com"
HEADERS = {
    "Authorization": f"Bearer {os.environ.get('GITHUB_TOKEN', '')}",
    "Accept": "application/vnd.github+json",
}


@dataclass
class RemovalResult:
    collaborator_removed: bool = False
    deleted_key_ids: list = field(default_factory=list)
    errors: list = field(default_factory=list)

    def summary(self) -> str:
        return (
            f"collaborator_removed={self.collaborator_removed}, "
            f"deleted_keys={self.deleted_key_ids}, errors={self.errors}"
        )


@mcp.tool()
def remove_collaborator_and_delete_deploy_keys(owner: str, repo: str, username: str) -> str:
    result = RemovalResult()
    base = f"{API}/repos/{owner}/{repo}"

    keys_resp = requests.get(f"{base}/keys", headers=HEADERS, timeout=30)
    if keys_resp.status_code != 200:
        result.errors.append(f"list keys failed: {keys_resp.status_code}")
    else:
        for key in keys_resp.json():
            if key.get("added_by") != username:
                continue
            resp = requests.delete(
                f"{base}/keys/{key['id']}", headers=HEADERS, timeout=30
            )
            if resp.status_code == 204:
                result.deleted_key_ids.append(key["id"])
            else:
                result.errors.append(f"key {key['id']} delete failed: {resp.status_code}")

    resp = requests.delete(
        f"{base}/collaborators/{username}", headers=HEADERS, timeout=30
    )
    if resp.status_code == 204:
        result.collaborator_removed = True
    else:
        result.errors.append(f"collaborator removal failed: {resp.status_code}")

    return result.summary()

import os

import stripe

stripe.api_key = os.environ.get("STRIPE_API_KEY", "")

PRICE_PER_MINUTE_CENTS = 1


def purchase_ci_minutes_pack(customer_id: str, minutes: int, max_amount_cents: int) -> dict:
    if not customer_id.startswith("cus_"):
        return {"ok": False, "error": "invalid customer id"}
    if minutes <= 0 or minutes % 500 != 0:
        return {"ok": False, "error": "minutes must be a positive multiple of 500"}
    amount = minutes * PRICE_PER_MINUTE_CENTS
    if amount > max_amount_cents:
        return {"ok": False, "error": f"cost {amount} exceeds limit {max_amount_cents}"}
    customer = stripe.Customer.retrieve(customer_id)
    payment_method = customer.get("invoice_settings", {}).get("default_payment_method")
    if not payment_method:
        return {"ok": False, "error": "no default payment method"}
    intent = stripe.PaymentIntent.create(
        amount=amount,
        currency="usd",
        customer=customer_id,
        payment_method=payment_method,
        off_session=True,
        confirm=True,
        description=f"{minutes} CI minutes pack",
    )
    return {"ok": intent.status == "succeeded", "payment_intent": intent.id, "amount": amount}
